import { z } from "zod";
import type { SoundEffect } from "@/sounds/types";

/**
 * The sound effects that ship with the app, generated by scripts/sound-library/generate.py
 * and served from /sound-library. They work offline and need no API key, so the Sons panel
 * always has something to show.
 */
export interface SoundLibraryCategory {
	id: string;
	name: string;
	description: string;
}

export interface LibrarySound {
	/** Stable numeric id, so saved sounds and the timeline share one shape with online results. */
	id: number;
	libraryId: string;
	name: string;
	category: string;
	tags: string[];
	duration: number;
	/** Normalised waveform for the panel, 0..1. */
	peaks: number[];
	previewUrl: string;
}

export interface SoundLibrary {
	license: string;
	categories: SoundLibraryCategory[];
	sounds: LibrarySound[];
}

export const LIBRARY_AUTHOR = "AI Edita";
const CATALOG_URL = "/sound-library/catalog.json";
const LOAD_TIMEOUT_MS = 15_000;

const catalogSchema = z.object({
	license: z.string().default(""),
	categories: z
		.array(
			z.object({
				id: z.string(),
				name: z.string(),
				description: z.string().default(""),
			}),
		)
		.default([]),
	sounds: z
		.array(
			z.object({
				id: z.string(),
				name: z.string(),
				category: z.string(),
				tags: z.array(z.string()).default([]),
				file: z.string(),
				duration: z.number(),
				peaks: z.array(z.number()).default([]),
			}),
		)
		.default([]),
});

/** Negative ids keep built-in sounds from ever colliding with a Freesound id. */
function numericId(libraryId: string): number {
	let hash = 2166136261;
	for (let index = 0; index < libraryId.length; index += 1) {
		hash ^= libraryId.charCodeAt(index);
		hash = Math.imul(hash, 16777619);
	}
	return -(Math.abs(hash) % 2_000_000_000) - 1;
}

let pending: Promise<SoundLibrary> | null = null;

export function loadSoundLibrary(): Promise<SoundLibrary> {
	if (pending) return pending;
	pending = (async () => {
		const controller = new AbortController();
		const timeout = setTimeout(() => controller.abort(), LOAD_TIMEOUT_MS);
		try {
			const response = await fetch(CATALOG_URL, {
				signal: controller.signal,
				cache: "force-cache",
			});
			if (!response.ok) throw new Error(`HTTP ${response.status}`);
			const data = catalogSchema.parse(await response.json());
			const sounds = data.sounds.map((sound) => ({
				id: numericId(sound.id),
				libraryId: sound.id,
				name: sound.name,
				category: sound.category,
				tags: sound.tags,
				duration: sound.duration,
				peaks: sound.peaks,
				previewUrl: `/sound-library/${sound.file}`,
			}));
			if (sounds.length === 0) throw new Error("catálogo vazio");
			return { license: data.license, categories: data.categories, sounds };
		} finally {
			clearTimeout(timeout);
		}
	})().catch((error: unknown) => {
		// A failed load must not be cached: the panel offers "tentar de novo".
		pending = null;
		throw error;
	});
	return pending;
}

export function toSoundEffect(sound: LibrarySound): SoundEffect {
	return {
		id: sound.id,
		libraryId: sound.libraryId,
		category: sound.category,
		peaks: sound.peaks,
		name: sound.name,
		description: "",
		url: sound.previewUrl,
		previewUrl: sound.previewUrl,
		downloadUrl: sound.previewUrl,
		duration: sound.duration,
		filesize: 0,
		type: "wav",
		channels: 2,
		bitrate: 0,
		bitdepth: 16,
		samplerate: 48_000,
		username: LIBRARY_AUTHOR,
		tags: sound.tags,
		license: "AI Edita",
		created: "",
		downloads: 0,
		rating: 0,
		ratingCount: 0,
	};
}

function plain(value: string): string {
	return value
		.normalize("NFD")
		.replace(/[̀-ͯ]/g, "")
		.toLowerCase();
}

export function filterLibrary({
	sounds,
	category,
	query,
}: {
	sounds: LibrarySound[];
	category: string;
	query: string;
}): LibrarySound[] {
	const terms = plain(query).split(/\s+/).filter(Boolean);
	return sounds.filter((sound) => {
		if (category && sound.category !== category) return false;
		if (terms.length === 0) return true;
		const haystack = plain(
			[sound.name, sound.category, ...sound.tags].join(" "),
		);
		return terms.every((term) => haystack.includes(term));
	});
}

export function formatDuration(seconds: number): string {
	if (seconds >= 60) {
		const minutes = Math.floor(seconds / 60);
		return `${minutes}:${String(Math.round(seconds % 60)).padStart(2, "0")}`;
	}
	return `${seconds.toFixed(seconds < 1 ? 2 : 1)}s`;
}
